create table administradores (user_id uuid primary key references auth.users(id) on delete restrict, criado_em timestamptz not null default now());
create table clientes (id bigint generated by default as identity primary key, owner_id uuid not null references administradores(user_id) on delete restrict, nome text not null, nome_busca text not null, ativo boolean not null default true, criado_em timestamptz not null, atualizado_em timestamptz not null, constraint ck_clientes_nome check (length(trim(nome)) > 0));
create table contas (id bigint generated by default as identity primary key, owner_id uuid not null references administradores(user_id) on delete restrict, cliente_id bigint not null references clientes(id), criado_em timestamptz not null, constraint uq_contas_owner_cliente unique(owner_id, cliente_id));
create table movimentacoes (id bigint generated by default as identity primary key, owner_id uuid not null references administradores(user_id) on delete restrict, cliente_id bigint not null references clientes(id), conta_id bigint not null references contas(id), tipo text not null, valor_centavos bigint not null, descricao text, ocorrido_em timestamptz not null, registrado_em timestamptz not null, movimentacao_original_id bigint references movimentacoes(id), motivo text, operacao_id text not null, impressao_operacao text not null, constraint uq_mov_owner_operacao unique(owner_id, operacao_id), constraint uq_mov_owner_original unique(owner_id, movimentacao_original_id), constraint ck_mov_valor check(valor_centavos > 0), constraint ck_mov_tipo check(tipo in ('COMPRA','PAGAMENTO','REVERSAO_COMPRA','ESTORNO_PAGAMENTO')), constraint ck_mov_reversao check((tipo in ('REVERSAO_COMPRA','ESTORNO_PAGAMENTO')) = (movimentacao_original_id is not null)), constraint ck_mov_motivo check(movimentacao_original_id is null or length(trim(coalesce(motivo,''))) > 0), constraint ck_mov_descricao_compra check(tipo <> 'COMPRA' or length(trim(coalesce(descricao,''))) > 0));
create index idx_clientes_owner_busca on clientes(owner_id, nome_busca);
create index idx_mov_owner_cliente_registrado on movimentacoes(owner_id, cliente_id, registrado_em);
create index idx_mov_owner_conta on movimentacoes(owner_id, conta_id);
